// Pinned Anon-RPC specifiers: the app answers the harness's two startup reads (workerHash, workerResolvers) itself,
// so starting Anon-RPC makes no direct, non-anonymous request at all (the stock harness reads a public node directly).
//
// - pins.json is generated by `bun run pin` (scripts/pin.ts), which also saves a hash-checked copy of each worker
//   bundle to public/w/<hash>.js, listed first so no third-party CDN sees users at startup.
// - Once a network works, the app reads the live specifier through the mixnet. If it differs, that is only a signal:
//   the network's next start does the normal live read (the stock Anon-RPC trust model). A runtime answer is never
//   saved as a trusted pin, because a lying RPC must not be able to choose which worker code we load.
// - A pin that can't boot (the network shipped a new worker) also falls back to the live read, so availability never
//   depends on the pin.
import pins from "./pins.json";
import type { NetworkName } from "./config";
import { SEL_HASH, SEL_RESOLVERS, encodeStrings, withOwnCopy } from "./resolvers";

export interface Pin { workerHash: string; resolvers: string[] }
type PinFile = Record<string, Pin & { address: string; selfHosted: boolean }>;
const FILE = pins as unknown as PinFile;
const STALE = (n: NetworkName) => `bp.pin.stale.${n}`;
/** A stale signal lasts a day; after that the built-in pin is tried again (it may have been the network's hiccup). */
const STALE_MS = 24 * 3600_000;

/** The built-in pin for a network, unless it was found stale recently (then: boot with a live read). */
export function currentPin(n: NetworkName): (Pin & { own?: string }) | undefined {
  const p = FILE[n];
  if (!p || isStale(n)) return undefined;
  return { ...p, own: p.selfHosted ? `w/${p.workerHash.slice(2)}.js` : undefined };
}

function isStale(n: NetworkName) {
  try { const t = Number(localStorage.getItem(STALE(n))); return t > 0 && Date.now() - t < STALE_MS; } catch { return false; }
}

/** A provider for the harness that answers the two specifier reads from the pin and refuses anything else, so a
 *  pinned boot can never make a direct request. */
export function pinnedProvider(n: NetworkName, address: string, siteBase: string) {
  const p = currentPin(n);
  return {
    request: async ({ method, params }: { method: string; params?: unknown[] }) => {
      const call = (params?.[0] ?? {}) as { to?: string; data?: string };
      if (p && method === "eth_call" && call.to?.toLowerCase() === address.toLowerCase()) {
        if (call.data?.startsWith(SEL_HASH)) return p.workerHash;
        if (call.data?.startsWith(SEL_RESOLVERS)) return encodeStrings(withOwnCopy(p.resolvers, p.own && new URL(p.own, siteBase).toString()));
      }
      throw new Error(`pinned specifier: refusing a direct ${method} (no pin for ${n})`);
    },
  };
}

export const hasPin = (n: NetworkName) => !!currentPin(n);

/** Compare the pin's hash with the live specifier, read through the mixnet. A difference only marks the pin stale. */
export async function checkPin(n: NetworkName, address: string, ethCall: (to: string, data: string) => Promise<string>): Promise<"same" | "stale"> {
  const p = FILE[n];
  const hash = await ethCall(address, SEL_HASH);
  if (p && hash.toLowerCase() === p.workerHash.toLowerCase()) return "same";
  markStale(n);
  return "stale";
}

/** This network's pin is out of date: its next start reads the specifier live. */
export function markStale(n: NetworkName) { try { localStorage.setItem(STALE(n), String(Date.now())); } catch {} }
